challenge.solution:
def word_count(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

print(word_count("the cat and the hat and the bat"))
# {'the': 3, 'cat': 1, 'and': 2, 'hat': 1, 'bat': 1}

